# Show connected-component boxes for the inconsistent transcriptions.
def boxes_of(grid):
 h,w=len(grid),len(grid[0]);bg=grid[0][0];cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg};out=[]
 while cells:
  seed=cells.pop();todo=[seed];comp={seed}
  while todo:
   r,c=todo.pop()
   for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
    if p in cells:cells.remove(p);comp.add(p);todo.append(p)
  rs=[p[0] for p in comp];cs=[p[1] for p in comp];out.append((min(rs),min(cs),max(rs)+1,max(cs)+1))
 return sorted(out)
